1	package registry
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Registry 是一个已打开的本地登记册。同一目录同时只能被一个 Registry
15	// 独占打开（目录内 flock）；单个 Registry 的方法可被多个 goroutine
16	// 并发调用，所有状态变更与落盘在同一把互斥锁内一次完成。
17	type Registry struct {
18		dir    string
19		store  *store
20		state  *snapshot
21		mu     sync.Mutex
22		closed bool
23		// now 返回当前时间，到期判断以此为准；生产环境为 time.Now，测试可替换。
24		now func() time.Time
25	}
26	
27	// Create 在 dir 新建并打开一个空登记册。调用者通过 dir 指定本机数据
28	// 位置；目录不存在会被创建。目录中已存在登记册数据时返回错误，
29	// 已有的数据不会被覆盖。
30	func Create(dir string) (*Registry, error) {
31		if strings.TrimSpace(dir) == "" {
32			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
33		}
34		if err := os.MkdirAll(dir, dirMode); err != nil {
35			return nil, fmt.Errorf("registry: 无法创建数据目录: %w", err)
36		}
37		if _, err := os.Stat(dataFile(dir)); err == nil {
38			return nil, fmt.Errorf("%w: %s 已存在登记册数据，应用 Open 打开", ErrAlreadyExists, dir)
39		} else if !errors.Is(err, os.ErrNotExist) {
40			return nil, fmt.Errorf("registry: 无法访问数据目录: %w", err)
41		}
42		lock, err := acquireLock(dir)
43		if err != nil {
44			return nil, err
45		}
46		// 取锁后再确认一次，避免与另一个进程的 Create 竞争。
47		if _, err := os.Stat(dataFile(dir)); err == nil {
48			_ = releaseLock(lock)
49			return nil, fmt.Errorf("%w: %s 已存在登记册数据", ErrAlreadyExists, dir)
50		}
51		st := &store{dir: dir, lock: lock}
52		s := newSnapshot()
53		if err := st.save(s); err != nil {
54			_ = releaseLock(lock)
55			return nil, err
56		}
57		return &Registry{dir: dir, store: st, state: s, now: time.Now}, nil
58	}
59	
60	// Open 打开 dir 中的已有登记册。数据文件缺失视为空目录的新建场景，
61	// 应使用 Create；数据存在但无法读取或解析时返回包裹 ErrCorrupt 的
62	// 错误，不会被静默当成空登记册。
63	func Open(dir string) (*Registry, error) {
64		if strings.TrimSpace(dir) == "" {
65			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
66		}
67		if info, err := os.Stat(dir); err != nil {
68			return nil, fmt.Errorf("registry: 无法打开数据目录: %w", err)
69		} else if !info.IsDir() {
70			return nil, fmt.Errorf("%w: %s 不是目录", ErrInvalidArgument, dir)
71		}
72		lock, err := acquireLock(dir)
73		if err != nil {
74			return nil, err
75		}
76		// 数据文件不存在不是"空登记册"：明确报错，提示用 Create 新建，
77		// 绝不把无数据目录静默当成空登记册。
78		if _, err := os.Stat(dataFile(dir)); err != nil {
79			_ = releaseLock(lock)
80			if errors.Is(err, os.ErrNotExist) {
81				return nil, fmt.Errorf("%w: %s 中没有登记册数据，请用 Create 新建", ErrNotFound, dir)
82			}
83			return nil, fmt.Errorf("registry: 无法访问登记册数据: %w", err)
84		}
85		s, err := load(dir)
86		if err != nil {
87			_ = releaseLock(lock)
88			return nil, err
89		}
90		return &Registry{dir: dir, store: &store{dir: dir, lock: lock}, state: s, now: time.Now}, nil
91	}
92	
93	// Close 正常关闭登记册并释放独占锁。关闭后不能再调用其他方法。
94	func (r *Registry) Close() error {
95		r.mu.Lock()
96		defer r.mu.Unlock()
97		if r.closed {
98			return nil
99		}
100		r.closed = true
101		return releaseLock(r.store.lock)
102	}
103	
104	func releaseLock(f *os.File) error {
105		err := f.Close() // Close 同时释放 flock
106		if err != nil {
107			return fmt.Errorf("registry: 关闭登记册失败: %w", err)
108		}
109		return nil
110	}
111	
112	func (r *Registry) checkOpen() error {
113		if r.closed {
114			return fmt.Errorf("registry: 登记册已关闭")
115		}
116		return nil
117	}
118	
119	// commit 将当前状态原子落盘；落盘失败时以磁盘内容为准重新加载，
120	// 避免内存状态与已持久化状态不一致。
121	func (r *Registry) commit() error {
122		if err := r.store.save(r.state); err != nil {
123			if s, lerr := load(r.dir); lerr == nil {
124				r.state = s
125			}
126			return err
127		}
128		return nil
129	}
130	
131	// ---- 账户 ----
132	
133	// RegisterAccount 以唯一编号登记账户，登记后即为可用状态。
134	func (r *Registry) RegisterAccount(id, metadata string) error {
135		r.mu.Lock()
136		defer r.mu.Unlock()
137		if err := r.checkOpen(); err != nil {
138			return err
139		}
140		if strings.TrimSpace(id) == "" {
141			return fmt.Errorf("%w: 账户编号不能为空", ErrInvalidArgument)
142		}
143		if _, ok := r.state.Accounts[id]; ok {
144			return fmt.Errorf("%w: 账户 %s", ErrAlreadyExists, id)
145		}
146		r.state.Accounts[id] = account{ID: id, Metadata: metadata, Active: true}
147		return r.commit()
148	}
149	
150	// DeactivateAccount 停用账户。停用后其原有藏品与历史仍可查询，但不能
151	// 再发行、发起或接收新的转让；停用不影响已经落盘的任何记录。
152	//
153	// 停用以保存成功为准：停用状态尚未原子替换原数据就发生写入错误（如数据
154	// 位置暂时无法写入）时，返回本次实际的保存错误，不返回成功，也不能用失败
155	// 后重新读取原数据时的错误取代它。即使原数据仍在、却暂时无法读取或解析、
156	// 状态未能按磁盘重建，同一个仍打开的登记册也必须保持停用前的样子：该账户
157	// 仍可用，编号与元数据不变，其已有藏品的持有人、版本与历史原样保留；其他
158	// 账户此前已经成功停用的状态不被恢复为可用。原数据仍可读取的普通保存失败
159	// 同样撤销本次变化，不依赖重新读取成功。随后另一次无关操作成功保存也不会
160	// 把这次未保存的停用夹带落盘。保存条件恢复后该账户仍按原有规则参与转让；
161	// 之后再次提交停用须重新完成保存，成功返回后才显示不可用，并按现有规则
162	// 拒绝其发起或接收新的转让。
163	func (r *Registry) DeactivateAccount(id string) error {
164		r.mu.Lock()
165		defer r.mu.Unlock()
166		if err := r.checkOpen(); err != nil {
167			return err
168		}
169		a, ok := r.state.Accounts[id]
170		if !ok {
171			return fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
172		}
173		if !a.Active {
174			return nil // 停用是幂等的终态，已停用直接成功，不要求再次写入
175		}
176		// 保存停用前的账户记录：停用以一次保存完成为准。commit 失败且磁盘
177		// 暂时不可读、状态未能按磁盘重建时据此显式撤销，否则这次未保存的停用
178		// 会留在当前已打开的登记册中（GetAccount 显示不可用、转让被按停用
179		// 拒绝），并被随后另一次成功保存夹带落盘。
180		prev := a
181		a.Active = false
182		r.state.Accounts[id] = a
183		if err := r.commit(); err != nil {
184			// commit 失败时已尝试按磁盘内容重建状态：重建成功则账户已随旧状态
185			// 整体恢复可用，写回的记录与磁盘一致；磁盘暂时不可读、状态未能重建
186			// 时本次停用仍在，显式恢复为停用前记录，藏品持有、版本与历史本就未
187			// 被触碰。返回实际写入错误，而非成功或重新读取时的错误。
188			r.state.Accounts[id] = prev
189			return err
190		}
191		return nil
192	}
