211	// 已登记且可用；后续只有该账户能发行该系列的藏品或封存该系列。
212	func (r *Registry) CreateSeries(id, creatorID, metadata string) error {
213		r.mu.Lock()
214		defer r.mu.Unlock()
215		if err := r.checkOpen(); err != nil {
216			return err
217		}
218		if strings.TrimSpace(id) == "" {
219			return fmt.Errorf("%w: 系列编号不能为空", ErrInvalidArgument)
220		}
221		creator, ok := r.state.Accounts[creatorID]
222		if !ok {
223			return fmt.Errorf("%w: 创建账户 %s", ErrNotFound, creatorID)
224		}
225		if !creator.Active {
226			return fmt.Errorf("%w: 创建账户 %s", ErrAccountInactive, creatorID)
227		}
228		if _, ok := r.state.Series[id]; ok {
229			return fmt.Errorf("%w: 系列 %s", ErrAlreadyExists, id)
230		}
231		r.state.Series[id] = series{ID: id, CreatorID: creatorID, Metadata: metadata}
232		return r.commit()
233	}
