274	func (req IssueRequest) validatePresent() error {
275		missing := []string{}
276		if strings.TrimSpace(req.Operator) == "" {
277			missing = append(missing, "operator")
278		}
279		if strings.TrimSpace(req.Reason) == "" {
280			missing = append(missing, "reason")
281		}
282		if strings.TrimSpace(req.RequestID) == "" {
283			missing = append(missing, "request_id")
284		}
285		if strings.TrimSpace(req.ItemID) == "" {
286			missing = append(missing, "item_id")
287		}
288		if strings.TrimSpace(req.SeriesID) == "" {
289			missing = append(missing, "series_id")
290		}
291		if strings.TrimSpace(req.BatchNo) == "" {
