303	func issueParamsSig(req IssueRequest) string {
304		b, _ := json.Marshal(struct {
305			Kind     string `json:"kind"`
306			ItemID   string `json:"item_id"`
307			SeriesID string `json:"series_id"`
308			BatchNo  string `json:"batch_no"`
309			Metadata string `json:"metadata"`
310			HolderID string `json:"holder_id"`
311			Reason   string `json:"reason"`
312		}{"issue", req.ItemID, req.SeriesID, req.BatchNo, req.Metadata, req.HolderID, req.Reason})
313		return string(b)
314	}
315	
316	// Issue 发行一件藏品。成功后持有版本为 1，初始持有人为 req.HolderID。
317	// 操作者必须是系列创建账户且可用，初始持有人必须已登记且可用，系列未
318	// 封存，藏品编号从未使用过。同一 (操作者, 请求号) 且业务参数相同的
319	// 重复提交返回首次结果；参数不同返回 ErrRequestConflict。
320	//
321	// 状态类拒绝的落盘失败时，与整批发行一致：返回保存错误（保留实际写入
322	// 错误）而非该业务错误，结果为空（无藏品编号、无持有人、无版本、无历史
323	// 序号、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；保存
324	// 条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝条件仍
325	// 在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则正常发行。
326	func (r *Registry) Issue(req IssueRequest) (IssueResult, error) {
327		if err := req.validatePresent(); err != nil {
328			return IssueResult{}, err
329		}
330		r.mu.Lock()
331		defer r.mu.Unlock()
332		if err := r.checkOpen(); err != nil {
333			return IssueResult{}, err
334		}
335	
336		key := requestKey(req.Operator, req.RequestID)
337		sig := issueParamsSig(req)
338		if prev, ok := r.state.Requests[key]; ok {
339			return r.replayIssue(prev, sig)
340		}
341	
342		bizErr := r.checkIssue(req)
343		if bizErr != nil {
344			if !isValidationErr(bizErr) {
345				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号并
346				// 落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
347				r.state.Requests[key] = request{
348					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
349					Params: sig, Rejected: true, Reason: errCode(bizErr),
350					ItemID: req.ItemID,
351				}
352				if err := r.commit(); err != nil {
353					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批发行一致——
354					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
355					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
356					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
357					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
358					// 的情形。整体返回空结果：无藏品编号、无持有人、无版本、
359					// 无历史序号、不标回放、结果中业务错误为空，error 保留
360					// 实际写入错误。
361					delete(r.state.Requests, key)
362					return IssueResult{}, err
363				}
364			}
365			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
366			return IssueResult{ItemID: req.ItemID, Err: bizErr}, bizErr
367		}
368	
369		seq := r.state.NextSeq + 1
370		r.state.NextSeq = seq
371		r.state.Items[req.ItemID] = item{
372			ID: req.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
373			Metadata: req.Metadata, IssuedTxID: seq,
374		}
375		r.state.Holdings[req.ItemID] = holding{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1}
376		r.state.History = append(r.state.History, historyEntry{
377			Seq: seq, Kind: "issue", ItemID: req.ItemID, Operator: req.Operator,
378			Reason: req.Reason, RequestID: req.RequestID,
379			FromID: "", ToID: req.HolderID, FromVersion: 0, ToVersion: 1,
380		})
381		r.state.Requests[key] = request{
382			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
383			Params: sig, ItemID: req.ItemID, ToID: req.HolderID, Version: 1, TxSeq: seq,
384		}
385		if err := r.commit(); err != nil {
386			return IssueResult{}, err
387		}
388		return IssueResult{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1, TxSeq: seq}, nil
389	}
390	
391	// checkIssue 按单件发行的优先级执行与整批共用的发行资格规则：参数合法
392	// 后，操作者的登记/停用问题优先于系列问题，系列问题内部依次为不存在、
393	// 已封存、操作者不是创建账户，藏品编号已占用又优先于初始持有人问题。
394	func (r *Registry) checkIssue(req IssueRequest) error {
395		return r.checkSingleIssueEligibility(req.Operator, req.SeriesID, req.ItemID, req.HolderID)
396	}
397	
398	func (r *Registry) replayIssue(prev request, sig string) (IssueResult, error) {
399		if prev.Kind != "issue" || prev.Params != sig {
400			return IssueResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
401				ErrRequestConflict, prev.Operator, prev.RequestID)
402		}
403		res := IssueResult{ItemID: prev.ItemID, OwnerID: prev.ToID, Version: prev.Version,
404			TxSeq: prev.TxSeq, Replayed: true}
405		if prev.Rejected {
406			res.Err = codeErr(prev.Reason)
407			return res, res.Err
408		}
409		return res, nil
410	}
