445	
446	func transferParamsSig(req TransferRequest) string {
447		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
448		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
449		// 冲突拒绝。
450		b, _ := json.Marshal(struct {
451			Kind          string `json:"kind"`
452			ItemID        string `json:"item_id"`
453			ExpectedOwner string `json:"expected_owner"`
454			ExpectedVer   int64  `json:"expected_version"`
455			ToID          string `json:"to_id"`
456			Price         int64  `json:"price,omitempty"`
457			Reason        string `json:"reason"`
458		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
459		return string(b)
460	}
461	
462	// transferOutcome 是一笔成功转让落盘后的执行结果，供各转让入口组装
463	// 各自的返回结构与请求记录。
464	type transferOutcome struct {
465		seq     int64      // 转让历史序号
466		fromID  string     // 转让前持有人
467		fromVer int64      // 转让前持有版本
468		royalty royaltyRec // 版税应付记录（含价款、明细与余款）
469	}
470	
471	// toVer 是转让后的持有版本。
472	func (o transferOutcome) toVer() int64 { return o.fromVer + 1 }
473	
474	// applyTransfer 完成一笔成功转让的全部状态变化：持有版本加一并换主、
475	// 追加转让历史、按所属系列的版税规则快照计算应付明细与归转让前持有人
476	// 的余款。直接转让、授权代转与整批转让共用这一段逻辑，保证同一笔转让
477	// 的持有、历史与金额记录始终一致；authID 为空表示直接转让。调用方负责
478	// 前置校验、请求结果登记与落盘，调用时必须持有锁且校验已通过。
479	func (r *Registry) applyTransfer(itemID, toID, operator, reason, requestID, authID string, price int64) transferOutcome {
480		h := r.state.Holdings[itemID]
481		seq := r.state.NextSeq + 1
482		r.state.NextSeq = seq
483		from := h.OwnerID
484		fromVer := h.Version
485		h.OwnerID = toID
486		h.Version = fromVer + 1
487		r.state.Holdings[itemID] = h
488		r.state.History = append(r.state.History, historyEntry{
489			Seq: seq, Kind: "transfer", ItemID: itemID, Operator: operator,
490			Reason: reason, RequestID: requestID,
491			FromID: from, ToID: toID, FromVersion: fromVer, ToVersion: fromVer + 1,
492			AuthID: authID,
493		})
494		// 版税按所属系列的规则快照计算；余款归转让前持有人。
495		it := r.state.Items[itemID]
496		royalty := newRoyaltyRec(seq, itemID, it.SeriesID, price,
497			r.state.Series[it.SeriesID].Royalty, from)
498		r.state.Royalties[seq] = royalty
499		return transferOutcome{seq: seq, fromID: from, fromVer: fromVer, royalty: royalty}
500	}
501	
502	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
503	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
504	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
505	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
506	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
507	// 请求重复提交（即使藏品后来已易手）返回首次结果。
508	//
509	// 状态类拒绝的落盘失败时，与整批转让一致：返回保存错误（保留实际写入
510	// 错误）而非该业务错误，结果为空（无藏品编号、无持有变化、无历史序号、
511	// 无金额、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；
512	// 保存条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝
513	// 条件仍在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则
514	// 正常转出。
515	//
516	// 成功转让同样以保存完成为准：持有换人、版本加一、转让历史、版税应付、
517	// 历史序号与请求结果都尚未写入原登记册而保存失败（如数据位置暂时无法
518	// 写入）时，返回实际保存错误而非转让成功，结果为空（不携带藏品编号、前后
519	// 持有人、版本、历史序号、价款、应付或余款，业务错误为空，不标回放）。
520	// 即使失败后原数据暂时无法读取、状态未能按磁盘重建，这笔转让也必须从当前
521	// 仍打开的登记册中整体撤销：藏品仍属于提交前的持有人、版本不增加、持有
522	// 列表与藏品历史保持原状、版税查询没有本次计算记录、收款账户不多出应付，
523	// 请求号与历史序号都不被消耗；失败前已存在的成功转让、应付与其他藏品记录
524	// 原样保留，随后另一次无关操作成功保存也不会把这笔未保存的转让一并写入。
525	// 读写条件恢复后用原操作者、请求号、原因和全部转让参数重新提交，按当时的
526	// 持有与账户状态重新判断：条件仍满足时正常完成一次转让（版本只增加一次、
527	// 序号紧接已有历史、不标回放），此后再次提交相同内容才回放这一笔已保存的
528	// 结果；恢复期间藏品已被另一笔合法转让转出的，原请求按现有版本冲突规则
529	// 拒绝，不能回放先前未保存的成功。
530	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
531		if err := req.validatePresent(); err != nil {
532			return TransferResult{}, err
533		}
534		r.mu.Lock()
535		defer r.mu.Unlock()
536		if err := r.checkOpen(); err != nil {
537			return TransferResult{}, err
538		}
539	
540		key := requestKey(req.Operator, req.RequestID)
541		sig := transferParamsSig(req)
542		if prev, ok := r.state.Requests[key]; ok {
543			return r.replayTransfer(prev, sig)
544		}
545	
546		bizErr := r.checkTransfer(req)
547		if bizErr != nil {
548			if !isValidationErr(bizErr) {
549				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
550				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
551				r.state.Requests[key] = request{
552					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
553					Params: sig, Rejected: true, Reason: errCode(bizErr),
554					ItemID: req.ItemID,
555				}
556				if err := r.commit(); err != nil {
557					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批转让一致——
558					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
559					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
560					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
561					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
562					// 的情形。整体返回空结果：无藏品编号、无持有变化、无历史
563					// 序号、无金额、不标回放、结果中业务错误为空，error 保留
564					// 实际写入错误。
565					delete(r.state.Requests, key)
566					return TransferResult{}, err
567				}
568			}
569			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
570			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
571		}
572	
573		// 回滚基点：本次成功转让的全部改动（持有换人、版本加一、历史、版税
574		// 应付、历史序号、请求结果）都必须以一次保存完成为准。记录改动前的
575		// 持有、历史长度与历史序号，保存失败且磁盘暂时不可读、状态未能按磁盘
576		// 重建时据此整体撤销，否则后续任何一次成功保存都会把这笔未保存的转让
577		// 带进登记册，造成"已换人、可回放"的幻影交易。
578		prevHolding := r.state.Holdings[req.ItemID]
579		prevNextSeq := r.state.NextSeq
580		prevHistLen := len(r.state.History)
581	
582		// 持有变化、历史、版税应付与请求结果在同一临界区内一次落盘。
583		out := r.applyTransfer(req.ItemID, req.ToID, req.Operator, req.Reason, req.RequestID, "", req.Price)
584		r.state.Requests[key] = request{
585			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
586			Params: sig, ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
587			Version: out.toVer(), TxSeq: out.seq,
588		}
589		if err := r.commit(); err != nil {
590			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已随
591			// 旧状态整体撤销（持有未换人、无本次历史与应付、请求记录不存在、
592			// 序号未消耗），无需再动；磁盘暂时不可读、状态未能重建时本次改动
593			// 仍在，据此把这笔未保存的转让全部撤销，让当前已打开的登记册回到
594			// 提交前状态，也不被随后另一次成功保存带入。返回空结果：无藏品
595			// 编号、无前后持有人、无版本、无历史序号、无价款/应付/余款、不标
596			// 回放、结果中业务错误为空，error 保留实际写入错误。
597			if _, pending := r.state.Requests[key]; pending {
598				delete(r.state.Requests, key)
599				delete(r.state.Royalties, out.seq)
600				r.state.History = r.state.History[:prevHistLen]
601				r.state.Holdings[req.ItemID] = prevHolding
602				r.state.NextSeq = prevNextSeq
603			}
604			return TransferResult{}, err
605		}
606		return TransferResult{ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
607			Version: out.toVer(), TxSeq: out.seq,
608			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
609			Remainder: out.royalty.Remainder}, nil
610	}
611	
612	// checkTransfer 按单件转让的优先级执行与整批共用的直接转让资格规则：
613	// 参数合法后，藏品及持有记录不存在优先于账户错误，操作者的登记和停用
614	// 问题优先于接收账户问题，接收账户问题优先于收发同人，收发同人又优先
615	// 于持有信息不符。
616	func (r *Registry) checkTransfer(req TransferRequest) error {
617		return r.checkSingleTransferEligibility(directTransferEligibility{
618			itemID:        req.ItemID,
619			operator:      req.Operator,
620			toID:          req.ToID,
621			expectedOwner: req.ExpectedOwner,
622			expectedVer:   req.ExpectedVer,
623		})
624	}
625	
626	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
627		if prev.Kind != "transfer" || prev.Params != sig {
628			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
629				ErrRequestConflict, prev.Operator, prev.RequestID)
630		}
631		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
632			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
633		if prev.Rejected {
634			res.Err = codeErr(prev.Reason)
635			return res, res.Err
636		}
637		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
638		// 价款与应付明细，不重复计入。
639		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
640		return res, nil
641	}
642	
643	// ---- 限时一次性代转授权 ----
644	
645	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
646	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
647	func authzCurrentStatus(a authzRec, now time.Time) string {
648		switch a.Status {
649		case "revoked":
650			return AuthRevoked
651		case "used":
652			return AuthUsed
653		}
654		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
655			return AuthExpired
656		}
657		return AuthActive
658	}
