660	func (req CreateAuthorizationRequest) validatePresent() error {
661		missing := []string{}
662		if strings.TrimSpace(req.Operator) == "" {
663			missing = append(missing, "operator")
664		}
665		if strings.TrimSpace(req.Reason) == "" {
666			missing = append(missing, "reason")
667		}
668		if strings.TrimSpace(req.RequestID) == "" {
669			missing = append(missing, "request_id")
670		}
671		if strings.TrimSpace(req.AuthID) == "" {
672			missing = append(missing, "auth_id")
673		}
674		if strings.TrimSpace(req.ItemID) == "" {
675			missing = append(missing, "item_id")
676		}
677		if strings.TrimSpace(req.TrusteeID) == "" {
678			missing = append(missing, "trustee_id")
679		}
680		if strings.TrimSpace(req.ToID) == "" {
681			missing = append(missing, "to_id")
682		}
683		if strings.TrimSpace(req.ExpectedOwner) == "" {
684			missing = append(missing, "expected_owner")
685		}
686		if req.ExpectedVer <= 0 {
687			missing = append(missing, "expected_version")
688		}
689		if req.ExpiresAt.IsZero() {
690			missing = append(missing, "expires_at")
691		}
692		if len(missing) > 0 {
693			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
694		}
695		if req.Price < 0 {
696			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
697		}
698		return nil
699	}
