701	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
702		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
703		// 仍可回放；改价则按请求号冲突拒绝。
704		b, _ := json.Marshal(struct {
705			Kind          string `json:"kind"`
706			AuthID        string `json:"auth_id"`
707			ItemID        string `json:"item_id"`
708			TrusteeID     string `json:"trustee_id"`
709			ToID          string `json:"to_id"`
710			ExpectedOwner string `json:"expected_owner"`
711			ExpectedVer   int64  `json:"expected_version"`
712			ExpiresAt     string `json:"expires_at"`
713			Price         int64  `json:"price,omitempty"`
714			Reason        string `json:"reason"`
715		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
716			req.ExpectedOwner, req.ExpectedVer,
717			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
718		return string(b)
719	}
720	
721	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
722	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
723	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
724	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
725	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
726	//
727	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
728	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
729	// 参数错误与引用不存在不占用请求号。
730	//
731	// 成功与状态类拒绝都以保存完成为准：本次结果尚未写入原登记册而保存失败
732	// （如数据位置暂时无法写入）时，返回实际保存错误，不报告创建成功，也不
733	// 只返回原业务拒绝；结果为空（授权编号与状态为空、绑定版本为零、不标
734	// 回放、业务错误为空），error 说明保存失败。即使失败后原数据暂时无法
735	// 读取、状态未能按磁盘重建，这次操作也不留下任何新增授权、创建记录或
736	// 请求号占用，授权历史序号不被消耗，后续其他操作成功保存也不会把这次
737	// 未保存的内容带进登记册。保存条件恢复后用完全相同的请求重提，按当时
738	// 的业务状态重新判断：拒绝条件仍在则重新保存此次拒绝并返回对应业务
739	// 错误（首次重提不标回放），状态已满足请求则正常创建。
740	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
741		if err := req.validatePresent(); err != nil {
742			return CreateAuthorizationResult{}, err
743		}
744		r.mu.Lock()
745		defer r.mu.Unlock()
746		if err := r.checkOpen(); err != nil {
747			return CreateAuthorizationResult{}, err
748		}
749	
750		now := r.now()
751		key := requestKey(req.Operator, req.RequestID)
752		sig := createAuthzParamsSig(req)
753		if prev, ok := r.state.Requests[key]; ok {
754			return r.replayCreateAuthz(prev, sig)
755		}
756	
757		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
758			if !isValidationErr(bizErr) {
759				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
760				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
761				r.state.Requests[key] = request{
762					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
763					Params: sig, Rejected: true, Reason: errCode(bizErr),
764					AuthID: req.AuthID, ItemID: req.ItemID,
765				}
766				if err := r.commit(); err != nil {
767					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让一致——
768					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
769					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
770					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
771					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
772					// 的情形。整体返回空结果：授权编号与状态为空、绑定版本
773					// 为零、不标回放、结果中业务错误为空，error 保留实际
774					// 写入错误。
775					delete(r.state.Requests, key)
776					return CreateAuthorizationResult{}, err
777				}
778			}
779			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
780		}
781	
782		h := r.state.Holdings[req.ItemID]
783		a := authzRec{
784			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
785			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
786			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
787		}
788		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
789		// 未保存的授权、创建记录与请求号占用都必须显式撤销，否则后续任何
790		// 一次成功保存都会把这份未保存的授权带进登记册。
791		prevAuthSeq := r.state.NextAuthSeq
792		prevEvents := len(r.state.AuthEvents)
793		r.state.Authzs[req.AuthID] = a
794		authSeq := prevAuthSeq + 1
795		r.state.NextAuthSeq = authSeq
796		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
797			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
798			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
799			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
800		})
801		r.state.Requests[key] = request{
802			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
803			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
804		}
805		if err := r.commit(); err != nil {
806			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
807			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
808			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销。
809			if _, ok := r.state.Requests[key]; ok {
810				delete(r.state.Requests, key)
811				delete(r.state.Authzs, req.AuthID)
812				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
813				r.state.NextAuthSeq = prevAuthSeq
814			}
815			return CreateAuthorizationResult{}, err
816		}
817		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
818	}
819	
820	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
821		h, ok := r.state.Holdings[req.ItemID]
822		if !ok {
823			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
824				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
825			}
826			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
827		}
828		op, ok := r.state.Accounts[req.Operator]
829		if !ok {
830			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
831		}
832		trustee, ok := r.state.Accounts[req.TrusteeID]
833		if !ok {
834			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
835		}
836		to, ok := r.state.Accounts[req.ToID]
837		if !ok {
838			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
839		}
840		if req.TrusteeID == req.Operator {
841			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
842		}
843		if req.ToID == req.Operator {
844			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
845		}
846		if !op.Active {
847			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
848		}
849		if !trustee.Active {
850			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
851		}
852		if !to.Active {
853			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
854		}
855		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
856		if _, exists := r.state.Authzs[req.AuthID]; exists {
857			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
858		}
859		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
860		if !req.ExpiresAt.After(now) {
861			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
862				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
863		}
864		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
865			req.Operator != h.OwnerID {
866			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
867				ErrConflict, req.ItemID, h.OwnerID, h.Version)
868		}
869		return nil
870	}
871	
872	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
873		if prev.Kind != "auth_create" || prev.Params != sig {
874			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
875				ErrRequestConflict, prev.Operator, prev.RequestID)
876		}
877		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
878			Status: AuthActive, Replayed: true}
879		if prev.Rejected {
880			res.Err = codeErr(prev.Reason)
881			return res, res.Err
882		}
883		return res, nil
884	}
885	
886	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
887		b, _ := json.Marshal(struct {
888			Kind   string `json:"kind"`
889			AuthID string `json:"auth_id"`
890			Reason string `json:"reason"`
891		}{"auth_revoke", req.AuthID, req.Reason})
892		return string(b)
893	}
894	
895	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销
896	// （非授权人返回 ErrForbidden）；已使用的授权不能撤销
897	// （ErrAuthorizationUsed）。授权已撤销时再次撤销不新增授权变更记录，按
898	// 成功返回。到期但未使用的授权仍可撤销（变更记录从 expired 记为
899	// revoked）。请求号语义与其他操作一致。
900	//
901	// 无权（ErrForbidden）与已使用（ErrAuthorizationUsed）两类业务拒绝同样
902	// 需要落盘：拒绝结果尚未写入原登记册而保存失败（如数据位置暂时无法写入）
903	// 时，返回实际保存错误，不能只返回上述业务错误让调用者误以为拒绝结果已经
904	// 记住；结果为空（无授权编号、无状态、业务错误为空、不标回放），error 保留
905	// 保存失败的原因。这次未保存的拒绝不改变授权内容、授权变更记录、藏品当前
906	// 持有人和版本，也不占用操作者的本次请求号——即使保存失败后原登记册数据
907	// 暂时无法读取、状态未能按磁盘重建，未保存的拒绝也不能留在当前已打开的
908	// 登记册中，或随之后另一次正常操作被保存下来。保存条件恢复后用同一操作者、
909	// 请求号、授权编号和原因重新提交，按当时的授权情况重新处理：拒绝条件仍存在
910	// 时先成功保存此次拒绝再返回相应业务错误（首次重提不标回放），此后完全相同
911	// 的提交才回放它；失败保存的请求不适用请求号冲突规则，该操作者用同号撤销另
912	// 一份自己有权撤销的授权时不会遭遇请求号冲突。必填内容缺失及授权不存在仍
913	// 直接按原错误拒绝、不占用请求号，不因当前无法保存而变成保存错误。
914	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
915		missing := []string{}
916		if strings.TrimSpace(req.Operator) == "" {
917			missing = append(missing, "operator")
918		}
919		if strings.TrimSpace(req.Reason) == "" {
920			missing = append(missing, "reason")
921		}
922		if strings.TrimSpace(req.RequestID) == "" {
923			missing = append(missing, "request_id")
924		}
925		if strings.TrimSpace(req.AuthID) == "" {
926			missing = append(missing, "auth_id")
927		}
928		if len(missing) > 0 {
929			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
930				ErrInvalidArgument, strings.Join(missing, ", "))
931		}
932		r.mu.Lock()
933		defer r.mu.Unlock()
934		if err := r.checkOpen(); err != nil {
935			return RevokeAuthorizationResult{}, err
936		}
937	
938		now := r.now()
939		key := requestKey(req.Operator, req.RequestID)
940		sig := revokeAuthzParamsSig(req)
941		if prev, ok := r.state.Requests[key]; ok {
942			return r.replayRevokeAuthz(prev, sig)
943		}
944	
945		a, ok := r.state.Authzs[req.AuthID]
946		if !ok {
947			// 引用不存在不占用请求号。
948			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
949			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
950		}
951		if a.GranterID != req.Operator {
952			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
953				ErrForbidden, a.GranterID, req.AuthID)
954			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
955				return RevokeAuthorizationResult{}, err
956			}
957			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
958		}
959		switch authzCurrentStatus(a, now) {
960		case AuthUsed:
961			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
962			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
963				return RevokeAuthorizationResult{}, err
964			}
965			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
966		case AuthRevoked:
967			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
968			// 相同请求重放回放同一结果。
969			r.state.Requests[key] = request{
970				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
971				Params: sig, AuthID: req.AuthID,
972			}
973			if err := r.commit(); err != nil {
974				return RevokeAuthorizationResult{}, err
975			}
976			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
977		}
978	
979		from := AuthActive
980		if authzCurrentStatus(a, now) == AuthExpired {
981			from = AuthExpired
982		}
983		a.Status = "revoked"
984		a.RevokedAt = now
985		r.state.Authzs[req.AuthID] = a
986		authSeq := r.state.NextAuthSeq + 1
987		r.state.NextAuthSeq = authSeq
988		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
989			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
990			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
991			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
992		})
993		r.state.Requests[key] = request{
994			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
995			Params: sig, AuthID: req.AuthID,
996		}
997		if err := r.commit(); err != nil {
998			return RevokeAuthorizationResult{}, err
999		}
1000		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
1001	}
1002	
1003	// recordRevokeRejection 登记撤销授权的状态类业务拒绝（非授权人的
1004	// ErrForbidden、授权人撤销已使用授权的 ErrAuthorizationUsed）并落盘。
1005	// 拒绝结果以保存完成为准：落盘失败时显式撤销尚未保存的请求号占用并返回
1006	// 实际保存错误，调用方必须返回空结果与该错误，不能只返回业务拒绝让调用者
1007	// 误以为拒绝已经记住；落盘成功时返回 nil，由调用方返回业务拒绝本身。
1008	func (r *Registry) recordRevokeRejection(key, sig string, req RevokeAuthorizationRequest, bizErr error) error {
1009		r.state.Requests[key] = request{
1010			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
1011			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1012		}
1013		if err := r.commit(); err != nil {
1014			// commit 失败时已尝试按磁盘内容重建状态，请求记录随之撤销；此处再
1015			// 删一次以覆盖磁盘暂时不可读、状态未能重建的情形——未保存的拒绝
1016			// 不能留在当前已打开的登记册中，也不能随随后另一次正常操作被保存。
1017			delete(r.state.Requests, key)
1018			return err
1019		}
1020		return nil
1021	}
1022	
1023	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
1024		if prev.Kind != "auth_revoke" || prev.Params != sig {
1025			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1026				ErrRequestConflict, prev.Operator, prev.RequestID)
1027		}
1028		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
1029		if prev.Rejected {
1030			res.Err = codeErr(prev.Reason)
1031			res.Status = ""
1032			return res, res.Err
1033		}
1034		return res, nil
1035	}
