1037	func proxyTransferParamsSig(req ProxyTransferRequest) string {
1038		b, _ := json.Marshal(struct {
1039			Kind   string `json:"kind"`
1040			AuthID string `json:"auth_id"`
1041			Reason string `json:"reason"`
1042		}{"proxy_transfer", req.AuthID, req.Reason})
1043		return string(b)
1044	}
1045	
1046	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
1047	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
1048	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
1049	// 操作者记为实际受托账户并可通过授权编号追溯。
1050	//
1051	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
1052	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
1053	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
1054	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
1055	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
1056	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
1057	//
1058	// 上述状态类拒绝以保存完成为准：拒绝结果尚未写入原登记册而保存失败（如
1059	// 数据位置暂时无法写入）时，返回实际保存错误，不能只返回到期、无权或停用
1060	// 等业务拒绝让调用者误以为这次拒绝已经记住；结果为空（不带授权或藏品编号、
1061	// 不带转让和金额信息、不标回放，结果内的业务错误也为空），error 保留实际
1062	// 写入失败原因。这次未保存的拒绝不改变授权内容、使用标记、授权变更记录，
1063	// 也不改变藏品持有人、版本、转让历史与版税应付，并不占用操作者的本次请求
1064	// 号——即使保存失败后原数据暂时无法读取、状态未能按磁盘重建，未保存的拒绝
1065	// 也不能留在当前已打开的登记册中，或随随后另一次成功保存被记住。保存条件
1066	// 恢复后用完全相同的请求重提，按重提时的业务状态重新判断，而不是回放失败
1067	// 时的拒绝（例如到期拒绝保存失败、授权随后被撤销时，重提返回已撤销）；这次
1068	// 重新处理若保存成功不标回放，此后原样重提才回放已保存的结果。已经成功保存
1069	// 的拒绝仍按首次结果回放，改动该请求的业务内容仍报请求号冲突；必填内容缺失
1070	// 或引用不存在沿用原错误且不占用请求号。
1071	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
1072		missing := []string{}
1073		if strings.TrimSpace(req.Operator) == "" {
1074			missing = append(missing, "operator")
1075		}
1076		if strings.TrimSpace(req.Reason) == "" {
1077			missing = append(missing, "reason")
1078		}
1079		if strings.TrimSpace(req.RequestID) == "" {
1080			missing = append(missing, "request_id")
1081		}
1082		if strings.TrimSpace(req.AuthID) == "" {
1083			missing = append(missing, "auth_id")
1084		}
1085		if len(missing) > 0 {
1086			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
1087				ErrInvalidArgument, strings.Join(missing, ", "))
1088		}
1089		r.mu.Lock()
1090		defer r.mu.Unlock()
1091		if err := r.checkOpen(); err != nil {
1092			return ProxyTransferResult{}, err
1093		}
1094	
1095		now := r.now()
1096		key := requestKey(req.Operator, req.RequestID)
1097		sig := proxyTransferParamsSig(req)
1098		if prev, ok := r.state.Requests[key]; ok {
1099			return r.replayProxyTransfer(prev, sig)
1100		}
1101	
1102		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
1103			if !isValidationErr(bizErr) {
1104				// 状态类业务拒绝（无权、已撤销、已到期、已使用、停用、版本已
1105				// 变化）占用请求号并落盘：相同参数重提返回这一次拒绝。
1106				r.state.Requests[key] = request{
1107					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1108					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1109				}
1110				if err := r.commit(); err != nil {
1111					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让、授权
1112					// 创建/撤销一致——不能用业务错误掩盖保存错误，调用者稍后用
1113					// 原请求重提时必须按当时状态重新判断，而不是回放一个实际没有
1114					// 保存的拒绝。此分支在写入前只动了请求记录，没有改变持有、
1115					// 授权或版税；commit 失败时已按磁盘内容重建状态，请求记录随之
1116					// 撤销，此处再删一次以覆盖磁盘暂时不可读、状态未能重建的情形。
1117					// 整体返回空结果：不带授权或藏品编号、不带转让和金额信息、不标
1118					// 回放、结果中业务错误为空，error 保留实际写入错误。
1119					delete(r.state.Requests, key)
1120					return ProxyTransferResult{}, err
1121				}
1122			}
1123			// 必填缺失、授权或账户不存在等校验错误不占用请求号，也不改变持有、
1124			// 授权状态或授权变更记录。
1125			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1126		}
1127	
1128		a := r.state.Authzs[req.AuthID]
1129		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
1130		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
1131		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
1132		// 追溯。
1133		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
1134		a.Status = "used"
1135		a.UsedTxSeq = out.seq
1136		a.UsedAt = now
1137		r.state.Authzs[a.ID] = a
1138		authSeq := r.state.NextAuthSeq + 1
1139		r.state.NextAuthSeq = authSeq
1140		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1141			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
1142			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1143			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
1144		})
1145		r.state.Requests[key] = request{
1146			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1147			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1148			Version: out.toVer(), TxSeq: out.seq,
1149		}
1150		if err := r.commit(); err != nil {
1151			return ProxyTransferResult{}, err
1152		}
1153		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1154			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1155			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1156			Remainder: out.royalty.Remainder}, nil
1157	}
1158	
1159	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1160		a, ok := r.state.Authzs[req.AuthID]
1161		if !ok {
1162			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1163		}
1164		op, ok := r.state.Accounts[req.Operator]
1165		if !ok {
1166			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1167		}
1168		granter, gOk := r.state.Accounts[a.GranterID]
1169		to, tOk := r.state.Accounts[a.ToID]
1170		if req.Operator != a.TrusteeID {
1171			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1172				ErrForbidden, req.Operator, req.AuthID)
1173		}
1174		if !gOk {
1175			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1176		}
1177		if !tOk {
1178			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1179		}
1180		if !op.Active {
1181			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1182		}
1183		if !granter.Active {
1184			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1185		}
1186		if !to.Active {
1187			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1188		}
1189		switch authzCurrentStatus(a, now) {
1190		case AuthRevoked:
1191			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1192		case AuthExpired:
1193			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1194		case AuthUsed:
1195			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1196		}
1197		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1198		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1199		h, ok := r.state.Holdings[a.ItemID]
1200		if !ok {
1201			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1202		}
1203		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1204			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1205				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1206		}
1207		return nil
1208	}
1209	
1210	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1211		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1212			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1213				ErrRequestConflict, prev.Operator, prev.RequestID)
1214		}
1215		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1216			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1217		if prev.Rejected {
1218			res.Err = codeErr(prev.Reason)
1219			return res, res.Err
1220		}
1221		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1222		// 原价款与应付明细，不重复计入。
1223		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1224		return res, nil
1225	}
