1229	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1230	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1231	// 到期但尚未终结的授权返回 AuthExpired。
1232	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1233		r.mu.Lock()
1234		defer r.mu.Unlock()
1235		if err := r.checkOpen(); err != nil {
1236			return Authorization{}, err
1237		}
1238		a, ok := r.state.Authzs[authID]
1239		if !ok {
1240			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1241		}
1242		return Authorization{
1243			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1244			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1245			Status:    authzCurrentStatus(a, r.now()),
1246			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1247			RevokedAt: a.RevokedAt,
1248		}, nil
1249	}
