1251	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1252	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1253	// 不存在时返回包裹 ErrNotFound 的错误。
1254	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1255		r.mu.Lock()
1256		defer r.mu.Unlock()
1257		if err := r.checkOpen(); err != nil {
1258			return nil, err
1259		}
1260		if _, ok := r.state.Items[itemID]; !ok {
1261			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1262		}
1263		out := make([]AuthorizationEvent, 0)
1264		for _, e := range r.state.AuthEvents {
1265			if e.ItemID != itemID {
1266				continue
1267			}
1268			out = append(out, AuthorizationEvent{
1269				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1270				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1271				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1272				OccurredAt: e.OccurredAt,
1273			})
1274		}
1275		return out, nil
1276	}
