1309	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1310	// ErrNotFound 的错误；停用账户仍可正常查询。
1311	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1312		r.mu.Lock()
1313		defer r.mu.Unlock()
1314		if err := r.checkOpen(); err != nil {
1315			return nil, err
1316		}
1317		if _, ok := r.state.Accounts[accountID]; !ok {
1318			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1319		}
1320		out := make([]Holding, 0)
1321		for _, h := range r.state.Holdings {
1322			if h.OwnerID == accountID {
1323				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1324			}
1325		}
1326		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1327		return out, nil
1328	}
