1330	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1331	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1332	// 返回包裹 ErrNotFound 的错误。
1333	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1334		r.mu.Lock()
1335		defer r.mu.Unlock()
1336		if err := r.checkOpen(); err != nil {
1337			return nil, err
1338		}
1339		if _, ok := r.state.Items[itemID]; !ok {
1340			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1341		}
1342		out := make([]HistoryEntry, 0)
1343		for _, e := range r.state.History {
1344			if e.ItemID != itemID {
1345				continue
1346			}
1347			out = append(out, HistoryEntry{
1348				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1349				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1350				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1351			})
1352		}
1353		return out, nil
1354	}
1355	
1356	// ---- 幂等辅助 ----
1357	
1358	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1359	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1360	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1361	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1362	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1363	func requestKey(operator, requestID string) string {
1364		b, _ := json.Marshal([2]string{operator, requestID})
1365		return string(b)
1366	}
1367	
1368	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1369	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1370	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1371	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1372	// 并回放。
1373	func isValidationErr(err error) bool {
1374		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1375	}
1376	
1377	var errCodes = map[error]string{
1378		ErrNotFound:             "not_found",
1379		ErrAlreadyExists:        "already_exists",
1380		ErrAccountInactive:      "account_inactive",
1381		ErrSeriesSealed:         "series_sealed",
1382		ErrConflict:             "conflict",
1383		ErrSameAccount:          "same_account",
1384		ErrForbidden:            "forbidden",
1385		ErrAuthorizationRevoked: "authorization_revoked",
1386		ErrAuthorizationExpired: "authorization_expired",
1387		ErrAuthorizationUsed:    "authorization_used",
1388		ErrRoyaltyFrozen:        "royalty_frozen",
1389		ErrSplitIntentRejected:  "split_intent_rejected",
1390		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1391		ErrSplitIntentInvalid:   "split_intent_invalid",
1392		ErrSplitIntentExpired:   "split_intent_expired",
1393		ErrSplitAnswered:        "split_answered",
1394	}
1395	
1396	var codeErrs = map[string]error{
1397		"not_found":              ErrNotFound,
1398		"already_exists":         ErrAlreadyExists,
1399		"account_inactive":       ErrAccountInactive,
1400		"series_sealed":          ErrSeriesSealed,
1401		"conflict":               ErrConflict,
1402		"same_account":           ErrSameAccount,
1403		"forbidden":              ErrForbidden,
1404		"authorization_revoked":  ErrAuthorizationRevoked,
1405		"authorization_expired":  ErrAuthorizationExpired,
1406		"authorization_used":     ErrAuthorizationUsed,
1407		"royalty_frozen":         ErrRoyaltyFrozen,
1408		"split_intent_rejected":  ErrSplitIntentRejected,
1409		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1410		"split_intent_invalid":   ErrSplitIntentInvalid,
1411		"split_intent_expired":   ErrSplitIntentExpired,
1412		"split_answered":         ErrSplitAnswered,
1413	}
1414	
1415	func errCode(err error) string {
1416		for sentinel, code := range errCodes {
1417			if errors.Is(err, sentinel) {
1418				return code
1419			}
1420		}
1421		return "rejected"
1422	}
1423	
1424	func codeErr(code string) error {
1425		if e, ok := codeErrs[code]; ok {
1426			return e
1427		}
1428		return errors.New("registry: 请求曾被拒绝")
1429	}
