863		// 旧请求仍可回放（旧签名不含价款，等价于价款 0）
864		ireq := IssueRequest{Operator: "alice", Reason: "首发", RequestID: "req-i1",
865			ItemID: "i1", SeriesID: "s1", BatchNo: "b1", HolderID: "alice"}
866		ires, err := r.Issue(ireq)
867		if err != nil || !ires.Replayed || ires.TxSeq != 1 {
868			t.Fatalf("legacy issue request must replay: %+v %v", ires, err)
869		}
870		treq := TransferRequest{Operator: "alice", Reason: "卖出", RequestID: "t1",
871			ItemID: "i1", ExpectedOwner: "alice", ExpectedVer: 1, ToID: "bob"}
872		tres, err := r.Transfer(treq)
873		if err != nil || !tres.Replayed || tres.TxSeq != 2 || tres.Price != 0 {
874			t.Fatalf("legacy transfer request must replay: %+v %v", tres, err)
875		}
876		// 旧请求改价重提 -> 请求号冲突
877		treq.Price = 5
878		if _, err := r.Transfer(treq); !errors.Is(err, ErrRequestConflict) {
879			t.Fatalf("legacy request with new price must conflict, got %v", err)
880		}
881		// 已有藏品的旧系列规则已固定；未发行的旧系列仍可设置规则
882		if _, err := r.SetRoyalty(setRoyaltyReq("n1", RoyaltyShare{AccountID: "carol", Rate: 1})); !errors.Is(err, ErrRoyaltyFrozen) {
883			t.Fatalf("legacy series with items must be frozen, got %v", err)
884		}
885		set2 := setRoyaltyReq("n2", RoyaltyShare{AccountID: "carol", Rate: 100})
886		set2.SeriesID = "s2"
887		if _, err := r.SetRoyalty(set2); err != nil {
888			t.Fatalf("legacy series without items must accept rule: %v", err)
889		}
890		// 新发行 + 新转让在旧登记册上正常记录版税（s2 规则 carol 1%）
891		ireq2 := issueReq("i2", "bob")
892		ireq2.SeriesID = "s2"
893		if _, err := r.Issue(ireq2); err != nil {
894			t.Fatal(err)
895		}
896		nreq := xferReq("bob", "i2", "carol", 1, "t2")
897		nreq.Price = 400
898		nres, err := r.Transfer(nreq)
899		if err != nil {
900			t.Fatal(err)
901		}
902		if nres.Price != 400 || len(nres.Payables) != 1 || nres.Payables[0].Amount != 4 ||
903			nres.Remainder != 396 {
904			t.Fatalf("new transfer on legacy registry wrong: %+v", nres)
