61		wantSharesEqual(t, cur, rule1...)
62	
63		// 首次发行前连续设置第二份不同规则，再清空规则。
64		mustSetRoyalty(t, r, "rs-2", rule2...)
65		mustSetRoyalty(t, r, "rs-3")
66	
67		evs, err := r.RoyaltyHistory("s1")
68		if err != nil {
69			t.Fatalf("RoyaltyHistory: %v", err)
70		}
71		if len(evs) != 3 {
72			t.Fatalf("三次真实变更应保留三条历史，得到 %d 条: %+v", len(evs), evs)
73		}
74	
75		// 三次变更的期望内容：第一次变更前为空；第二次变更前等于第一次
76		// 设置的内容；清空记录变更后为空。
77		type meta struct {
78			seq             int64
79			op, reason, rid string
80			at              time.Time
81			before, after   []RoyaltyShare
82		}
83		wantEvents := []struct {
84			seq           int64
85			rid           string
86			before, after []RoyaltyShare
87		}{
88			{seq: 1, rid: "rs-1", before: nil, after: rule1},
89			{seq: 2, rid: "rs-2", before: rule1, after: rule2},
90			{seq: 3, rid: "rs-3", before: rule2, after: nil},
91		}
92		saved := make([]meta, len(evs))
93		for i, w := range wantEvents {
94			e := evs[i]
95			if e.Seq != w.seq || e.SeriesID != "s1" || e.Operator != "alice" ||
96				e.Reason != "设定版税" || e.RequestID != w.rid {
97				t.Fatalf("第 %d 条记录元数据错误: %+v", i+1, e)
98			}
99			if e.OccurredAt.IsZero() {
100				t.Fatalf("第 %d 条记录缺少发生时间", i+1)
101			}
102			wantSharesEqual(t, e.Before, w.before...)
103			wantSharesEqual(t, e.After, w.after...)
104			saved[i] = meta{
105				seq: e.Seq, op: e.Operator, reason: e.Reason, rid: e.RequestID,
106				at:     e.OccurredAt,
107				before: append([]RoyaltyShare(nil), e.Before...),
108				after:  append([]RoyaltyShare(nil), e.After...),
109			}
110		}
111	
112		// 同一份查询结果中，相邻记录内容相同的 After/Before 也必须彼此独立：
113		// event1 的 After 与 event2 的 Before 都是 rule1，改一处不能连带另一处。
114		evs[0].After[0].AccountID = "hacker"
115		evs[0].After[0].Rate = 1111
116		if evs[1].Before[0].AccountID != "carol" || evs[1].Before[0].Rate != 2500 {
117			t.Fatalf("修改上一条的 After 连带改掉了下一条的 Before: %+v", evs[1].Before)
118		}
119		// event2 的 After 与 event3 的 Before 都是 rule2（两条份额各自独立）。
120		evs[1].After[0].Rate = 2222
121		evs[1].After[1].AccountID = "mallory"
122		if evs[2].Before[0].AccountID != "bob" || evs[2].Before[0].Rate != 1000 ||
123			evs[2].Before[1].AccountID != "dave" || evs[2].Before[1].Rate != 500 {
124			t.Fatalf("修改第二条的 After 连带改掉了清空记录的 Before: %+v", evs[2].Before)
125		}
126		// 首次设置的空 Before 与清空记录的空 After 也是互不影响的独立切片。
127		evs[0].Before = append(evs[0].Before, RoyaltyShare{AccountID: "ghost", Rate: 1})
128		if len(evs[2].After) != 0 {
129			t.Fatalf("向第一条的空 Before 追加不应影响清空记录的 After: %+v", evs[2].After)
130		}
131		evs[2].After = append(evs[2].After, RoyaltyShare{AccountID: "ghost", Rate: 2})
132		if len(evs[0].Before) != 1 || evs[0].Before[0].AccountID != "ghost" {
133			t.Fatalf("调用者自己的追加应保留在本地副本中: %+v", evs[0].Before)
134		}
135	
136		// 大幅改写调用者自己拿到的记录字段与前后列表，甚至整条替换为零值。
137		evs[1].Seq = 999
138		evs[1].SeriesID = "sX"
139		evs[1].Operator = "mallory"
140		evs[1].Reason = "被篡改的原因"
141		evs[1].RequestID = "fake-req"
142		evs[1].OccurredAt = evs[1].OccurredAt.Add(365 * 24 * time.Hour)
143		evs[1].Before = []RoyaltyShare{{AccountID: "zzz", Rate: 1}}
144		evs[1].After = evs[1].After[:0]
145		evs[2] = RoyaltyEvent{}
146	
147		// 本地修改不构成一次规则设置：当前规则仍是清空状态，历史条数不变。
148		cur, err = r.GetSeriesRoyalty("s1")
149		if err != nil {
150			t.Fatal(err)
151		}
152		if len(cur) != 0 {
153			t.Fatalf("篡改历史副本不得改变当前规则: %+v", cur)
154		}
155	
156		// 重新查询应得到原先保存的完整内容：账户、比例、前后列表、操作者、
157		// 原因、请求号、时间与记录序号全部保持原值。
158		fresh, err := r.RoyaltyHistory("s1")
159		if err != nil {
160			t.Fatalf("RoyaltyHistory: %v", err)
161		}
162		if len(fresh) != 3 {
163			t.Fatalf("篡改本地副本不得增减历史记录，得到 %d 条", len(fresh))
164		}
165		for i, w := range wantEvents {
166			e := fresh[i]
167			s := saved[i]
168			if e.Seq != s.seq || e.Operator != s.op || e.Reason != s.reason ||
169				e.RequestID != s.rid || e.SeriesID != "s1" || !e.OccurredAt.Equal(s.at) {
170				t.Fatalf("第 %d 条记录元数据被本地修改污染: %+v（原值 %+v）", i+1, e, s)
171			}
172			wantSharesEqual(t, e.Before, w.before...)
173			wantSharesEqual(t, e.After, w.after...)
174		}
175	
176		// 两次查询得到的结果互不共享底层数据。
177		a, _ := r.RoyaltyHistory("s1")
178		b, _ := r.RoyaltyHistory("s1")
179		a[0].After[0].Rate = 4242
180		a[0].After = a[0].After[:0]
181		a = append(a, RoyaltyEvent{Seq: 1})
182		if len(b) != 3 || b[0].After[0].AccountID != "carol" || b[0].After[0].Rate != 2500 {
183			t.Fatalf("一份查询结果被改写后，另一份查询结果必须保持原样: %+v", b)
184		}
185		b[1].Before[0].AccountID = "zzz"
186		if fresh[1].Before[0].AccountID != "carol" || fresh[1].Before[0].Rate != 2500 {
187			t.Fatalf("查询结果的改动不得影响其他查询已拿到的内容: %+v", fresh[1].Before)
188		}
189	
190		// 本地修改不消耗真实的变更记录序号：随后真正的设置拿到序号 4，
191		// 其变更前仍是清空状态。
192		mustSetRoyalty(t, r, "rs-4", RoyaltyShare{AccountID: "dave", Rate: 7})
193		again, err := r.RoyaltyHistory("s1")
194		if err != nil {
195			t.Fatal(err)
196		}
197		if len(again) != 4 || again[3].Seq != 4 || again[3].RequestID != "rs-4" {
198			t.Fatalf("本地篡改不应产生或消耗变更序号: %+v", again)
199		}
200		wantSharesEqual(t, again[3].Before)
201		wantSharesEqual(t, again[3].After, RoyaltyShare{AccountID: "dave", Rate: 7})
202	}
203	
204	// TestRoyaltyHistorySnapshotVsLaterSetIssueTransfer 覆盖历史查询结果与
205	// 后续正常设置、发行、转让之间的关系：保留的旧结果只代表取得时的历史，
206	// 新查询才出现新记录；无论怎样修改旧副本，当前规则查询、首次发行后的
207	// 固定规则以及转让时的版税计算都只以登记册中真正设置过的规则为准。
208	func TestRoyaltyHistorySnapshotVsLaterSetIssueTransfer(t *testing.T) {
209		r := mustCreate(t, tempDir(t))
210		royaltyWorld(t, r)
211	
212		ruleA := []RoyaltyShare{{AccountID: "carol", Rate: 2000}}
213		ruleB := []RoyaltyShare{{AccountID: "bob", Rate: 1000}, {AccountID: "dave", Rate: 3333}}
214	
215		// 第一份真实规则，调用者随即保留一份历史结果。
216		mustSetRoyalty(t, r, "rs-1", ruleA...)
217		old, err := r.RoyaltyHistory("s1")
218		if err != nil {
219			t.Fatalf("RoyaltyHistory: %v", err)
220		}
221		if len(old) != 1 {
222			t.Fatalf("首次设置后应只有一条历史，得到 %+v", old)
223		}
224		firstAt := old[0].OccurredAt
225	
226		// 调用者为整理展示内容大幅改写自己保留的这份历史（账户、比例、
227		// 前后列表、操作者、原因、请求号、序号、时间全部改）。
228		old[0].Seq = 77
229		old[0].SeriesID = "sX"
230		old[0].Operator = "mallory"
231		old[0].Reason = "伪造的原因"
232		old[0].RequestID = "fake-req"
233		old[0].OccurredAt = firstAt.Add(100 * time.Hour)
234		old[0].Before = append(old[0].Before, RoyaltyShare{AccountID: "ghost", Rate: 1})
235		old[0].After[0].AccountID = "hacker"
236		old[0].After[0].Rate = 9999
237	
238		// 系列创建账户使用新的请求号设置另一份规则：以登记册真实状态成功，
239		// 历史副本里的 hacker/9999 不构成任何规则。
240		mustSetRoyalty(t, r, "rs-2", ruleB...)
241	
242		// 旧查询结果继续表示取得时的历史（仍只有一条，本地改写原样保留）。
243		if len(old) != 1 || old[0].After[0].AccountID != "hacker" || old[0].After[0].Rate != 9999 {
244			t.Fatalf("保留的旧结果应仍是调用者取得时的那份副本: %+v", old)
245		}
246	
247		// 当前规则查询返回最后一次真正设置的规则 ruleB。
248		cur, err := r.GetSeriesRoyalty("s1")
249		if err != nil {
250			t.Fatal(err)
251		}
252		wantSharesEqual(t, cur, ruleB...)
253	
254		// 新查询才出现新增记录和新的前后内容，全部是真实保存过的内容。
255		fresh, err := r.RoyaltyHistory("s1")
256		if err != nil {
257			t.Fatalf("RoyaltyHistory: %v", err)
258		}
259		if len(fresh) != 2 {
260			t.Fatalf("新查询应出现两条历史，得到 %d 条", len(fresh))
261		}
262		if fresh[0].Seq != 1 || fresh[0].RequestID != "rs-1" || fresh[0].Operator != "alice" ||
263			fresh[0].Reason != "设定版税" || !fresh[0].OccurredAt.Equal(firstAt) {
264			t.Fatalf("第一条记录元数据错误: %+v", fresh[0])
265		}
266		wantSharesEqual(t, fresh[0].Before)
267		wantSharesEqual(t, fresh[0].After, ruleA...)
268		wantSharesEqual(t, fresh[1].Before, ruleA...)
269		wantSharesEqual(t, fresh[1].After, ruleB...)
270	
271		// 首次发行后规则固定：篡改历史副本不可能打开设置入口，冻结拒绝也
272		// 不新增变更记录。
273		if _, err := r.Issue(issueReq("i1", "alice")); err != nil {
274			t.Fatalf("Issue: %v", err)
275		}
276		if _, err := r.SetRoyalty(setRoyaltyReq("rs-3",
277			RoyaltyShare{AccountID: "hacker", Rate: 9999})); !errors.Is(err, ErrRoyaltyFrozen) {
278			t.Fatalf("首次发行后必须按 ErrRoyaltyFrozen 拒绝，得到 %v", err)
279		}
280		frozen, err := r.RoyaltyHistory("s1")
281		if err != nil {
282			t.Fatal(err)
283		}
284		if len(frozen) != 2 {
285			t.Fatalf("冻结拒绝不得新增变更记录，历史条数 = %d", len(frozen))
286		}
287	
288		// 成功转让：成交金额以分计，版税按真实规则 ruleB 计算，各账户分别
289		// 按万分之一比例向下取整，而不是按历史副本里改出的账户或比例。
290		req := xferReq("alice", "i1", "bob", 1, "t-1")
291		req.Price = 12345
292		res, err := r.Transfer(req)
293		if err != nil {
294			t.Fatalf("Transfer: %v", err)
295		}
296		if res.Price != 12345 {
297			t.Fatalf("成交金额应以分记录: %d", res.Price)
298		}
299		pm := payableMap(t, res.Payables)
300		if len(pm) != 2 {
301			t.Fatalf("只应为真实规则中的两个账户记账: %+v", res.Payables)
302		}
303		// 12345 * 1000 / 10000 = 1234.5 -> 向下取整 1234
304		// 12345 * 3333 / 10000 = 4114.5885 -> 向下取整 4114
305		if p := pm["bob"]; p.Rate != 1000 || p.Amount != 1234 {
306			t.Fatalf("bob 的应付应为比例 1000、金额 1234，得到 %+v", p)
307		}
308		if p := pm["dave"]; p.Rate != 3333 || p.Amount != 4114 {
309			t.Fatalf("dave 的应付应为比例 3333、金额 4114，得到 %+v", p)
310		}
311		if _, ok := pm["hacker"]; ok {
312			t.Fatalf("历史副本中改出的 hacker 账户不应产生应付: %+v", res.Payables)
313		}
314		if _, ok := pm["carol"]; ok {
315			t.Fatalf("已被替换的旧规则账户 carol 不应再参与计算: %+v", res.Payables)
316		}
317		// 余款归转让前持有人 alice。
318		if res.Remainder != 12345-1234-4114 {
319			t.Fatalf("余款金额错误: %d", res.Remainder)
320		}
321		ro, err := r.TransferRoyalty(res.TxSeq)
322		if err != nil {
323			t.Fatalf("TransferRoyalty: %v", err)
324		}
325		if ro.Price != 12345 || ro.OwnerID != "alice" || ro.Remainder != 12345-1234-4114 {
326			t.Fatalf("转让版税记录错误: %+v", ro)
327		}
328	
329		// 由此产生的应付只归原（真实）规则的账户。
330		for acct, wantAmt := range map[string]int64{"bob": 1234, "dave": 4114} {
331			entries, err := r.PayablesOf(acct)
332			if err != nil {
333				t.Fatalf("PayablesOf %s: %v", acct, err)
334			}
335			if len(entries) != 1 || entries[0].Amount != wantAmt {
336				t.Fatalf("账户 %s 的应付应为一笔 %d，得到 %+v", acct, wantAmt, entries)
337			}
338		}
339		entries, err := r.PayablesOf("carol")
340		if err != nil {
341			t.Fatalf("PayablesOf carol: %v", err)
342		}
343		if len(entries) != 0 {
344			t.Fatalf("旧规则账户 carol 不应有应付明细: %+v", entries)
345		}
346	
347		// 全部操作结束后，旧副本仍只代表取得时的那一条本地内容。
348		if len(old) != 1 || old[0].RequestID != "fake-req" {
349			t.Fatalf("旧副本不应被后续真实操作覆盖: %+v", old)
350		}
351	}
352	
353	// TestRoyaltyHistoryEmptyForSeriesWithoutRule 覆盖从未设置过版税的已登记
354	// 系列始终返回空历史；设置与清空产生的空前后列表彼此独立，也不影响
355	// 其他系列的查询结果。
356	func TestRoyaltyHistoryEmptyForSeriesWithoutRule(t *testing.T) {
357		r := mustCreate(t, tempDir(t))
358		royaltyWorld(t, r)
359	
360		// s1 已登记但从未设置版税：空历史、空当前规则。
361		evs, err := r.RoyaltyHistory("s1")
362		if err != nil {
363			t.Fatalf("RoyaltyHistory: %v", err)
364		}
365		if len(evs) != 0 {
366			t.Fatalf("未设置过规则的系列应返回空历史，得到 %+v", evs)
367		}
368		rule, err := r.GetSeriesRoyalty("s1")
369		if err != nil {
370			t.Fatal(err)
371		}
372		if len(rule) != 0 {
373			t.Fatalf("未设置过规则的系列当前规则应为空: %+v", rule)
374		}
375	
376		// 在空结果上追加、改写本地内容，不产生变更也不改变再次查询。
377		evs = append(evs, RoyaltyEvent{
378			Seq: 1, Operator: "mallory",
379			After: []RoyaltyShare{{AccountID: "bob", Rate: 1}},
380		})
381		evs[0].After[0].Rate = 9999
382		again, err := r.RoyaltyHistory("s1")
383		if err != nil || len(again) != 0 {
384			t.Fatalf("篡改空历史本地副本不应产生记录: %+v %v", again, err)
385		}
386		rule, _ = r.GetSeriesRoyalty("s1")
387		if len(rule) != 0 {
388			t.Fatalf("篡改空历史本地副本不应设置规则: %+v", rule)
389		}
390	
391		// 另一个已登记系列 s2 独立返回空历史。
392		if err := r.CreateSeries("s2", "alice", ""); err != nil {
393			t.Fatal(err)
394		}
395		s2hist, err := r.RoyaltyHistory("s2")
396		if err != nil || len(s2hist) != 0 {
397			t.Fatalf("s2 应返回空历史: %+v %v", s2hist, err)
398		}
399	
400		// 在 s1 上设置再清空：产生的空 Before/空 After 互不影响，也不影响 s2。
401		mustSetRoyalty(t, r, "rs-1", RoyaltyShare{AccountID: "carol", Rate: 100})
402		h1, err := r.RoyaltyHistory("s1")
403		if err != nil {
404			t.Fatal(err)
405		}
406		if len(h1) != 1 || len(h1[0].Before) != 0 {
407			t.Fatalf("首次设置的变更前应为空列表: %+v", h1)
408		}
409		h1[0].Before = append(h1[0].Before, RoyaltyShare{AccountID: "zzz", Rate: 1})
410		h1[0].After[0].Rate = 4242
411		h1[0].After[0].AccountID = "xxx"
412	
413		mustSetRoyalty(t, r, "rs-2") // 清空
414		cl, err := r.RoyaltyHistory("s1")
415		if err != nil {
416			t.Fatal(err)
417		}
418		if len(cl) != 2 || len(cl[0].Before) != 0 || len(cl[1].After) != 0 {
419			t.Fatalf("设置/清空两条记录的空前后列表形状错误: %+v", cl)
420		}
421		cl[0].Before = append(cl[0].Before, RoyaltyShare{AccountID: "a", Rate: 1})
422		cl[0].After[0].AccountID = "xxx"
423		cl[1].After = append(cl[1].After, RoyaltyShare{AccountID: "b", Rate: 2})
424		cl[1].Before[0].Rate = 7
425	
426		final1, err := r.RoyaltyHistory("s1")
427		if err != nil {
428			t.Fatal(err)
429		}
430		if len(final1) != 2 {
431			t.Fatalf("s1 历史应仍为两条，得到 %d 条", len(final1))
432		}
433		if len(final1[0].Before) != 0 {
434			t.Fatalf("第一条的空 Before 被污染: %+v", final1[0].Before)
435		}
436		wantSharesEqual(t, final1[0].After, RoyaltyShare{AccountID: "carol", Rate: 100})
437		wantSharesEqual(t, final1[1].Before, RoyaltyShare{AccountID: "carol", Rate: 100})
438		if len(final1[1].After) != 0 {
439			t.Fatalf("清空记录的 After 应仍为空: %+v", final1[1].After)
440		}
441		final2, err := r.RoyaltyHistory("s2")
442		if err != nil || len(final2) != 0 {
443			t.Fatalf("s1 的本地改写不应影响 s2 的空历史: %+v %v", final2, err)
444		}
445	
446		// 未设置过规则的系列首次发行后固定为无版税，历史仍为空。
447		ireq := issueReq("i-s2", "bob")
448		ireq.SeriesID = "s2"
449		if _, err := r.Issue(ireq); err != nil {
450			t.Fatalf("Issue on s2: %v", err)
451		}
452		post, err := r.RoyaltyHistory("s2")
453		if err != nil || len(post) != 0 {
454			t.Fatalf("未设置过规则的系列发行后历史仍应为空: %+v %v", post, err)
455		}
456		rule2, err := r.GetSeriesRoyalty("s2")
457		if err != nil || len(rule2) != 0 {
458			t.Fatalf("未设置过规则的系列应固定为空规则: %+v %v", rule2, err)
459		}
460	}
