	// 那次未保存的成功；拒绝不改变持有。
	res, err = r.Transfer(req)
	if !errors.Is(err, ErrConflict) {
		t.Fatalf("藏品已转出后原请求应按版本冲突拒绝: %v", err)
	}
	if res.Replayed || res.ItemID != "i1" || !errors.Is(res.Err, ErrConflict) ||
		res.Version != 0 || res.TxSeq != 0 {
		t.Fatalf("冲突拒绝的结果异常: %+v", res)
