		t.Fatalf("冲突拒绝保存后再提应回放该拒绝: %+v, err %v", res, err)
	}
	h, _ = r.GetHolding("i1")
	if h.OwnerID != "alice" || h.Version != 2 {
		t.Fatalf("回放冲突拒绝不应改变持有: %+v", h)
	}
}

